// The screening rules: validate each applicant, then accept, review or reject.
// Thresholds come from the config table, so changing one is an UPDATE, not an edit here.
const cfg = $('Config').first().json.config;
const MIN_FOLLOWERS = Number(cfg.min_followers);
const REVIEW_FOLLOWERS = Number(cfg.review_followers);

// A missing threshold would compare false against every number and accept everybody.
if (!Number.isFinite(MIN_FOLLOWERS) || !Number.isFinite(REVIEW_FOLLOWERS) || MIN_FOLLOWERS > REVIEW_FOLLOWERS) {
  throw new Error(`bad thresholds in config: ${cfg.min_followers} / ${cfg.review_followers}`);
}

const ALLOWED = ['youtube', 'tiktok', 'instagram'];

// Derived from the application id, never random, so re-running the pipeline
// gives an applicant the same code instead of a second one.
function trackingCode(s) {
  const fnv = (seed) => {
    let h = seed;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h.toString(16).toUpperCase().padStart(8, '0');
  };
  return `CP-${fnv(0x811c9dc5)}${fnv(0x9dc5811c)}`;
}

const out = [];

for (const a of $input.all().flatMap((item) => item.json.data ?? [])) {
  const external_id = String(a.external_id ?? '').trim();
  const email = String(a.email ?? '').trim().toLowerCase();
  const handle = String(a.handle ?? '').trim().replace(/^@/, '');
  const platform = String(a.platform ?? '').trim().toLowerCase();
  const followers = a.followers;

  const errors = [];
  if (!external_id) errors.push('external_id is required');
  if (!email.includes('@')) errors.push('email is not valid');
  if (!handle) errors.push('handle is required');
  if (!ALLOWED.includes(platform)) errors.push(`unsupported platform '${platform}'`);
  if (!Number.isInteger(followers) || followers < 0) errors.push('followers must be a non-negative integer');

  if (errors.length) {
    out.push({ json: { ...a, valid: false, decision: 'invalid', reason: errors.join('; ') } });
    continue;
  }

  let decision;
  if (followers < MIN_FOLLOWERS) decision = 'rejected';
  else if (followers < REVIEW_FOLLOWERS) decision = 'review';
  else decision = 'accepted';

  out.push({ json: {
    external_id, email, handle, platform, followers,
    valid: true, decision, reason: `${followers} followers`,
    tracking_code: trackingCode(external_id),
  } });
}

return out;

// One item per post, each carrying its creator's tracking code.
return $input.all().flatMap((item) =>
  (item.json.data ?? []).map((post) => ({ json: { tracking_code: item.json.tracking_code, ...post } })));
